/** The modules every bundle carries. */
export const RUNTIME_MODULES: Readonly<Record<string, string>> = {
  "pletivo-runtime.js": GENERATED_MODULES["pletivo-runtime.js"],
  "pletivo-isolate-protocol.js": GENERATED_MODULES["pletivo-isolate-protocol.js"],
  "pletivo-jsx-runtime.js": GENERATED_MODULES["pletivo-jsx-runtime.js"],
};

/** The module compiled `.astro` output imports, via the compiler's `internalURL`. */
export const RUNTIME_MODULE_NAME = "pletivo-runtime.js";

/** The module compiled JSX imports, via sucrase's `jsxImportSource`. */
export const JSX_RUNTIME_MODULE_NAME = "pletivo-jsx-runtime.js";

/** The module a project's content API resolves to. Added only when it is reached for. */
export const CONTENT_MODULE_NAME = "pletivo-content.js";

/** The module `astro:i18n` resolves to. Added only when reached for. */
export const I18N_MODULE_NAME = "pletivo-i18n.js";

/** The module `astro:assets` and an `image()` schema resolve through. Added only when reached for. */
export const IMAGE_MODULE_NAME = "pletivo-image.js";

/** The protocol module shared by the host and the isolate entry. */
export const ISOLATE_PROTOCOL_MODULE_NAME = "pletivo-isolate-protocol.js";

/** The Loader's main module. Never a project path. */
export const ISOLATE_ENTRY_MODULE_NAME = "pletivo-entry.js";

/** The per-program data module the host generates; see `IsolateProgram` in isolate-entry.ts. */
export const ISOLATE_PROGRAM_MODULE_NAME = "pletivo-program.js";

/** The entry modules every Loader program carries next to its data module. */
export const ISOLATE_ENTRY_MODULES: Readonly<Record<string, string>> = {
  "pletivo-entry.js": GENERATED_MODULES["pletivo-entry.js"],
  "pletivo-isolate-entry.js": GENERATED_MODULES["pletivo-isolate-entry.js"],
};

/** The Tailwind isolate's request handling; exports `createTailwindEntry`. */
export const TAILWIND_ENTRY_MODULE_NAME = "pletivo-tailwind-entry.js";

/** The module the Tailwind entry imports `tailwindcss` from. The artifact holds its source. */
export const TAILWIND_MODULE_NAME = "pletivo-tailwind.js";

/** The entry, which every Tailwind isolate program carries next to Tailwind and its plugins. */
export const TAILWIND_ISOLATE_MODULES: Readonly<Record<string, string>> = {
  "pletivo-tailwind-entry.js": GENERATED_MODULES["pletivo-tailwind-entry.js"],
};

/** The MDX isolate's request handling; exports `createMdxEntry`. */
export const MDX_ENTRY_MODULE_NAME = "pletivo-mdx-entry.js";

/** The entry, which every MDX isolate program carries next to the project's plugins. */
export const MDX_ISOLATE_MODULES: Readonly<Record<string, string>> = {
  "pletivo-mdx-entry.js": GENERATED_MODULES["pletivo-mdx-entry.js"],
};

/** The compiler isolate's main module; it imports the wasm from `COMPILER_WASM_MODULE_NAME`. */
export const COMPILER_MAIN_MODULE_NAME = "pletivo-compiler-main.js";

/** The module the host hands `astro.wasm`'s bytes as. */
export const COMPILER_WASM_MODULE_NAME = "pletivo-astro-compiler.wasm";

/** The compiler isolate's JavaScript; the host adds the wasm. */
export const COMPILER_ISOLATE_MODULES: Readonly<Record<string, string>> = {
  "pletivo-compiler-main.js": GENERATED_MODULES["pletivo-compiler-main.js"],
  "pletivo-compiler-entry.js": GENERATED_MODULES["pletivo-compiler-entry.js"],
};
